var e={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Автоматизируйте принтер с помощью безопасных правил «ЕСЛИ — ТО». По умолчанию выключены; включайте каждое правило вручную.`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Правил пока нет. Добавьте одно ниже, затем активируйте, когда будете готовы.`}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:`Движок правил ВКЛЮЧЁН`}},off:{t:0,b:{t:2,i:[{t:3}],s:`Движок правил ВЫКЛЮЧЕН`}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:`Включить`}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:`Выключить`}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:`Ничего не сработает, пока не включены и движок, и само правило.`}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:`Когда печать завершается`}},print_error:{t:0,b:{t:2,i:[{t:3}],s:`Когда у принтера возникает ошибка`}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:`Когда нагреватель поднимается выше`}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:`Когда нагреватель опускается ниже`}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:`Записать уведомление`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`Выполнить команду g-code`}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:`Активно`}},arm:{t:0,b:{t:2,i:[{t:3}],s:`Отключено`}},edit:{t:0,b:{t:2,i:[{t:3}],s:`Изменить`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Удалить`}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:`Удалить правило`}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:`Название правила`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`напр. Выключить нагреватели после печати`}},trigger:{t:0,b:{t:2,i:[{t:3}],s:`Если (триггер)`}},action:{t:0,b:{t:2,i:[{t:3}],s:`То (действие)`}},heater:{t:0,b:{t:2,i:[{t:3}],s:`Нагреватель`}},value:{t:0,b:{t:2,i:[{t:3}],s:`Температура (°C)`}},message:{t:0,b:{t:2,i:[{t:3}],s:`Сообщение`}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Показывается в журнале правила`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`напр. TURN_OFF_HEATERS`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Сохранить правило`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Отмена`}},add:{t:0,b:{t:2,i:[{t:3}],s:`Добавить правило`}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:`Недавняя активность`}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:`уведомлено`}},ran:{t:0,b:{t:2,i:[{t:3}],s:`выполнен g-code`}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:`пропущено (принтер занят)`}},error:{t:0,b:{t:2,i:[{t:3}],s:`ошибка`}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Руководство`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Руководство по движку правил`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Закрыть`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Что такое движок правил?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Он следит за принтером и выполняет действие, когда выполняется заданное вами условие — например, записывает заметку при завершении печати или выключает нагреватели. Каждое правило — это ЕСЛИ (триггер) ТО (действие).`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`Как обеспечивается безопасность`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Движок по умолчанию выключен, и каждое правило нужно активировать отдельно, поэтому ничего не сработает неожиданно. Правило срабатывает один раз, когда его условие впервые становится истинным. Действия с g-code выполняются только когда принтер простаивает — во время печати они отклоняются — и каждый результат записывается в журнал.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Глоссарий`}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:`Триггер`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Условие, запускающее правило, напр. завершение печати или пересечение нагревателем заданной температуры.`}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:`Действие`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Что делает правило при срабатывании: записывает уведомление или выполняет команду g-code (только при простое).`}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:`Активно`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Правило, которое включено. Отключённые правила сохраняются, но никогда не срабатывают.`}}}}}}};export{e as default};